public class Main {
    static final long MOD = 998244353L;

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long A = fs.nextLong();
        long B = fs.nextLong();
        long K = fs.nextLong();

        long[] fact = new long[N + 1];
        long[] invFact = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N] = modPow(fact[N], MOD - 2);
        for (int i = N; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long ans = 0;

        // Let:
        // x = number of red layers
        // y = number of green layers
        // z = number of blue layers
        //
        // Score = A*x + (A+B)*y + B*z = A*(x+y) + B*(y+z)
        //
        // Define p = x+y, q = y+z.
        // Then score = A*p + B*q.
        //
        // For fixed p,q:
        // y can be any integer in [max(0, p+q-N), min(p,q)].
        // For each y:
        // x = p-y, z = q-y, uncolored = N-(x+y+z) = N-p-q+y
        //
        // Number of colorings for fixed (x,y,z):
        // N! / (x! y! z! (N-x-y-z)!)
        //
        // Summing over y gives:
        // C(N,p) * C(N,q)
        // by Vandermonde's identity.
        //
        // Therefore answer is:
        // sum over p,q in [0..N], A*p + B*q = K of C(N,p)C(N,q).

        if (A == 0 && B == 0) {
            // Every painted/unpainted configuration has score 0.
            // 4 choices per layer.
            if (K == 0) {
                System.out.println(modPow(4, N));
            } else {
                System.out.println(0);
            }
            return;
        }

        if (A == 0) {
            // Need B*q = K, q in [0..N], answer = C(N,q) * sum_p C(N,p) = C(N,q)*2^N
            if (K % B != 0) {
                System.out.println(0);
                return;
            }
            long q = K / B;
            if (q < 0 || q > N) {
                System.out.println(0);
                return;
            }
            long ansSpecial = comb(N, (int) q, fact, invFact) * modPow(2, N) % MOD;
            System.out.println(ansSpecial);
            return;
        }

        if (B == 0) {
            // Need A*p = K, p in [0..N], answer = C(N,p) * 2^N
            if (K % A != 0) {
                System.out.println(0);
                return;
            }
            long p = K / A;
            if (p < 0 || p > N) {
                System.out.println(0);
                return;
            }
            long ansSpecial = comb(N, (int) p, fact, invFact) * modPow(2, N) % MOD;
            System.out.println(ansSpecial);
            return;
        }

        for (int p = 0; p <= N; p++) {
            long rem = K - A * p;
            if (rem < 0) continue;
            if (rem % B != 0) continue;
            long q = rem / B;
            if (q < 0 || q > N) continue;
            ans += comb(N, p, fact, invFact) * comb(N, (int) q, fact, invFact) % MOD;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

